using System;using System.IO;using System.Linq;using System.Text;using System.Security.Cryptography;using NUnit.Framework;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Tilemaps;namespace Rootborn.Tests.EditMode.Interiors{public sealed class HouseComfyDecorationAssetTests{
public static string GeometrySignature(Scene scene){var text=new StringBuilder();foreach(var root in scene.GetRootGameObjects().Where(r=>r.name!="HouseComfyFixedProps"&&r.name!="HouseResidents").OrderBy(r=>r.name)){foreach(var t in root.GetComponentsInChildren<Transform>(true).OrderBy(t=>PathOf(t)))text.AppendLine("transform "+PathOf(t)+" "+SchoolPrepCanonicalMatrix(t)+" "+t.gameObject.activeSelf);foreach(var map in root.GetComponentsInChildren<Tilemap>(true).OrderBy(m=>m.name)){text.AppendLine("map "+map.name+" "+map.transform.localToWorldMatrix);foreach(var c in map.cellBounds.allPositionsWithin)if(map.HasTile(c)&&!IsApprovedWallSeal(map,c)){text.AppendLine(map.name+" cell="+c);if(map.name!="HouseDecorationTilemap")text.AppendLine(" tile="+AssetDatabase.GetAssetPath(map.GetTile(c))+" matrix="+(map.name=="HouseGroundTilemap"?Matrix4x4.identity:map.GetTransformMatrix(c))+" color="+map.GetColor(c));}}foreach(var collider in root.GetComponentsInChildren<Collider2D>(true).OrderBy(c=>PathOf(c.transform))){text.AppendLine("collider "+PathOf(collider.transform)+" "+collider.GetType().Name+" "+collider.isTrigger+" "+collider.enabled+" "+collider.offset);if(collider is BoxCollider2D box)text.AppendLine("size="+box.size);}foreach(var s in root.GetComponentsInChildren<SpriteRenderer>(true).OrderBy(s=>PathOf(s.transform))){var spritePath=SchoolPrepCanonicalSpritePath(s);if(PathOf(s.transform)=="AuthoredOwnRoom/StudentDayEndBoard/Visual"&&spritePath=="Assets/Art/HousePixels/Furniture31/house_day_end_bed.png")spritePath="Assets/moderninteriors-win/1_Interiors/32x32/Theme_Sorter_Singles_32x32/4_Bedroom_Singles_32x32/Bedroom_Singles_32x32_1.png";text.AppendLine("sprite "+PathOf(s.transform)+" "+spritePath);}foreach(var p in root.GetComponentsInChildren<Rootborn.Game.World.WorldPortal>(true))text.AppendLine("portal "+PathOf(p.transform)+" "+p.DestinationScene+" "+p.DestinationSpawnId);}return BitConverter.ToString(SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(text.ToString()))).Replace("-","");}static string PathOf(Transform t)=>t.parent==null?t.name:PathOf(t.parent)+"/"+t.name;

// HouseResidents (Mom and her home anchors, added 2026-11-07 with the owner's approval) is new content, not historical geometry.
// Three wall cells the owner approved on 2026-11-05: without them the player can walk out of the room.
static bool IsApprovedWallSeal(Tilemap map,Vector3Int c)=>map.name=="HouseCollisionTilemap"&&((c.x==0&&c.y==-9)||(c.x==13&&c.y==-5)||(c.x==-14&&c.y==4));

// Canonicalize only the reviewed dedicated school-prep replacements. All actual
// translations, rotations, other scales, colliders, portals and paths remain hashed.
static bool IsAcceptedNotebook(Transform t)=>PathOf(t)=="AuthoredOwnRoom/DailyPlanBoard/Notebook"&&t.localScale==Vector3.one&&t.GetComponent<SpriteRenderer>()!=null&&AssetDatabase.GetAssetPath(t.GetComponent<SpriteRenderer>().sprite)=="Assets/Art/HousePixels/SchoolPrep31/school_prep_notebook.png";
static Matrix4x4 SchoolPrepCanonicalMatrix(Transform t){var matrix=t.localToWorldMatrix;return IsAcceptedNotebook(t)?matrix*Matrix4x4.Scale(new Vector3(2f,2f,2f)):matrix;}
static string SchoolPrepCanonicalSpritePath(SpriteRenderer renderer){string path=AssetDatabase.GetAssetPath(renderer.sprite);if(IsAcceptedNotebook(renderer.transform))return "Assets/Art/CareerFacilities/Supplement/notebook.png";if(PathOf(renderer.transform)=="AuthoredOwnRoom/DailyPlanBoard/NameTag"&&path=="Assets/Art/HousePixels/SchoolPrep31/school_prep_name_tag.png")return "Assets/Art/CareerFacilities/Supplement/child_name_tag.png";return path;}
[TestCase("NotebookPosition")][TestCase("NotebookScale")][TestCase("NameTagPosition")]
public void SchoolPrepCanonicalizationStillDetectsUnapprovedGeometryChange(string change){
 const string scenePath="Assets/Scenes/House.unity";
 Assert.That(SceneManager.GetSceneByPath(scenePath).isLoaded,Is.False,"This negative guard owns an additive House instance only.");
 byte[] savedBefore=File.ReadAllBytes(scenePath);var prior=SceneManager.GetActiveScene();var scene=EditorSceneManager.OpenScene(scenePath,OpenSceneMode.Additive);
 try{
  string expected=File.ReadAllText("output/design-comfy-20261031/evidence/house31-original-geometry-signature.txt").Trim();
  Assert.That(GeometrySignature(scene),Is.EqualTo(expected),"Reviewed replacement must first preserve historical geometry.");
  var all=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).ToArray();
  var notebook=all.Single(t=>PathOf(t)=="AuthoredOwnRoom/DailyPlanBoard/Notebook");var tag=all.Single(t=>PathOf(t)=="AuthoredOwnRoom/DailyPlanBoard/NameTag");
  // Mutate only this disposable scene instance. Signature canonicalization itself never writes transforms.
  if(change=="NotebookPosition")notebook.localPosition+=new Vector3(.125f,0,0);
  else if(change=="NotebookScale")notebook.localScale=new Vector3(1.25f,1.25f,1.25f);
  else if(change=="NameTagPosition")tag.localPosition+=new Vector3(0,.125f,0);
  else Assert.Fail("Unknown negative fixture case");
  Assert.That(GeometrySignature(scene),Is.Not.EqualTo(expected),"Canonicalization must retain sensitivity to "+change);
 }finally{EditorSceneManager.CloseScene(scene,true);if(prior.IsValid()&&prior.isLoaded)SceneManager.SetActiveScene(prior);Assert.That(File.ReadAllBytes(scenePath),Is.EqualTo(savedBefore),"Owned negative scene must never be saved.");}
}
[TestCase("plant")][TestCase("sofa_south")][TestCase("desk_south")][TestCase("desk_west")][TestCase("chair_south")][TestCase("chair_west")][TestCase("computer")]public void FixedSceneryHasDurablePointSpriteWithFirstCellFloorPivot(string name){string path="Assets/Art/HousePixels/Comfy31/House31_"+name+"_1x1.png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null);Assert.That(s.texture,Is.Not.Null);Assert.That(s.rect.width,Is.EqualTo(48));Assert.That(s.pixelsPerUnit,Is.EqualTo(48));Assert.That(s.pivot,Is.EqualTo(new Vector2(24,24)));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));}
[Test]public void ExistingHouseLayoutCollidersPortalsAndOriginalPropsArePreserved(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/House.unity",OpenSceneMode.Additive);try{Assert.That(GeometrySignature(scene),Is.EqualTo(File.ReadAllText("output/design-comfy-20261031/evidence/house31-original-geometry-signature.txt").Trim()));}finally{EditorSceneManager.CloseScene(scene,true);}}
[Test]public void AllFourteenDecorationCellsUseRealUntintedTextureReferences(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/House.unity",OpenSceneMode.Additive);try{var map=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Tilemap>(true)).Single(m=>m.name=="HouseDecorationTilemap");int count=0;foreach(var c in map.cellBounds.allPositionsWithin)if(map.HasTile(c)){var t=map.GetTile<Tile>(c);Assert.That(t,Is.Not.Null);Assert.That(t.sprite,Is.Not.Null);Assert.That(t.sprite.texture,Is.Not.Null,"Serialized placeholder texture missing at "+c);Assert.That(AssetDatabase.GetAssetPath(t),Does.StartWith("Assets/Data/Interiors/TileSets/HouseComfy31/"));Assert.That(map.GetColor(c),Is.EqualTo(Color.white));count++;}Assert.That(count,Is.EqualTo(14));}finally{EditorSceneManager.CloseScene(scene,true);}}
[Test]public void FourteenOwnedVisualsUseFloorDepthAndNoNewColliders(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/House.unity",OpenSceneMode.Additive);try{var root=scene.GetRootGameObjects().SingleOrDefault(r=>r.name=="HouseComfyFixedProps");Assert.That(root,Is.Not.Null);var maps=root.GetComponentsInChildren<Tilemap>(true);Assert.That(maps.Length,Is.EqualTo(14));Assert.That(root.GetComponentsInChildren<Collider2D>(true),Is.Empty);var old=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Tilemap>(true)).Single(m=>m.name=="HouseDecorationTilemap");Assert.That(old.GetComponent<TilemapRenderer>().enabled,Is.False);foreach(var m in maps){var r=m.GetComponent<TilemapRenderer>();Assert.That(r.mode,Is.EqualTo(TilemapRenderer.Mode.Individual));Assert.That(r.sortingOrder,Is.EqualTo(10000-Mathf.RoundToInt(m.GetCellCenterWorld(Vector3Int.zero).y*48)));Assert.That(m.GetTile(Vector3Int.zero),Is.Not.Null);}}finally{EditorSceneManager.CloseScene(scene,true);}}
[Test]public void ExistingFloorTileReusesReviewedComfyOakWithoutGeometryChange(){var t=AssetDatabase.LoadAssetAtPath<Tile>("Assets/Data/Interiors/TileSets/HousePersistentRepair/HouseRepair_floor.asset");var s=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/SchoolPixels/Comfy31/School_oak_floor_48.png");Assert.That(t.sprite,Is.SameAs(s));Assert.That(t.colliderType,Is.EqualTo(Tile.ColliderType.None));Assert.That(t.transform.lossyScale,Is.EqualTo(Vector3.one));}
}}

